'use strict';
let map=null,mapFilter='all',mapLayer=null,mapMarkers=new Map(),mapBounds=[],mapSource=null,mapRequest=0;
let leafletPromise=null;
function loadLeaflet(){if(window.L)return Promise.resolve();if(!leafletPromise)leafletPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/leaflet.js';script.onload=resolve;script.onerror=()=>{leafletPromise=null;reject(Error('地图模块尚未缓存或网络不可用'));};document.head.append(script);});return leafletPromise;}
function disposeMap(){mapRequest++;if(map){map.remove();map=null;}mapLayer=null;mapMarkers.clear();}
function mapPage(){return `<header class="utility-header"><p class="editor-label">ROUTE ATLAS</p><h1>路线地图</h1><p>本地底图与行程点位 · 示意连线，非道路导航路线。</p><div class="utility-actions"><button data-mapday="all" aria-pressed="${mapFilter==='all'}">全程</button><button data-map-dates>${mapFilter==='all'?'选择单日':dateText(DATA.days[+mapFilter-1].date)} ⌄</button><button data-fit>适应路线</button></div></header><div class="map-wrap"><div id="routeMap" class="map" aria-label="互动路线地图"><p class="map-loading">正在打开地图…</p></div></div><p class="info-caption">连线按原计划顺序连接地点；地图不含实时路况。Google / Apple 导航需联网。集合点与停车点均按原路书资料标注。</p><div id="selectedMapPlace" class="map-selection" aria-live="polite"></div><div id="mapPlaces" class="map-place-list"></div><div class="utility-actions"><button data-map-return>← 返回原行程</button>${mapFilter!=='all'?`<button data-day="${mapFilter}">打开当日安排 →</button>`:''}</div>`;}
async function initMap(){const token=++mapRequest;try{await loadLeaflet();if(token!==mapRequest||state.view!=='map'||!$('#routeMap'))return;$('#routeMap').textContent='';map=L.map('routeMap',{scrollWheelZoom:false,attributionControl:true,zoomAnimation:!reduced(),fadeAnimation:!reduced(),markerZoomAnimation:!reduced()});L.geoJSON(GEO,{style:{color:'#a7bcc4',weight:.7,fillColor:'#e6edeb',fillOpacity:1}}).addTo(map);map.attributionControl.addAttribution('本地边界：Natural Earth · 路线示意');mapLayer=L.layerGroup().addTo(map);updateMap();requestAnimationFrame(()=>map?.invalidateSize());}catch(e){if(token!==mapRequest)return;$('#routeMap').innerHTML='<p class="map-loading">互动地图暂不可用，仍可使用下方地点与导航列表。</p>';renderMapList();}}
function mapItems(){const days=mapFilter==='all'?DATA.days:[DATA.days[+mapFilter-1]];const items=[];for(const d of days){let keys=selectedRoute(d);for(const b of DATA.bookings.filter(b=>b.day===d.id)){for(const key of [b.parking,b.meeting||b.spot].filter(Boolean))if(!keys.includes(key))keys=[...keys,key];}for(const key of keys){const p=DATA.places[key];if(!p)continue;if(mapFilter==='all'&&p.lon>40)continue;if(!items.some(x=>x.key===key))items.push({key,p,day:d.id});}}return items;}
function placeKind(key){if(DATA.bookings.some(b=>b.parking===key)||/停车|Parking/.test(DATA.places[key]?.name||''))return '停车地点';if(DATA.bookings.some(b=>(b.meeting||b.spot)===key))return '活动集合 / 报到';return '行程地点';}
function renderMapList(){const items=mapItems();$('#mapPlaces').innerHTML=items.map((x,i)=>`<article class="map-place-row" data-map-row="${x.key}"><button data-map-place="${x.key}"><span class="map-order">${i+1}</span><span><strong>${esc(x.p.name)}</strong><small>${placeKind(x.key)} · ${shortDate(DATA.days[x.day-1].date)}</small></span><span>↗</span></button><div class="map-row-actions"><button data-navigation="${x.key}">地图导航</button><button data-day="${x.day}">当天安排</button><button data-place="${x.key}">地点详情</button></div></article>`).join('')||'<p>此日仅机场抵达，详见当日安排。</p>';}
function updateMap(){renderMapList();if(!map||!mapLayer)return;mapLayer.clearLayers();mapMarkers.clear();mapBounds=[];const days=mapFilter==='all'?DATA.days.filter(d=>d.id<18):[DATA.days[+mapFilter-1]];for(const d of days){const points=selectedRoute(d).map(k=>DATA.places[k]).filter(p=>p&&(mapFilter!=='all'||p.lon<40));if(points.length>1)L.polyline(points.map(p=>[p.lat,p.lon]),{color:'#557f8a',weight:2,opacity:.7,dashArray:'5 7'}).addTo(mapLayer);}mapItems().forEach((x,i)=>{mapBounds.push([x.p.lat,x.p.lon]);const marker=L.marker([x.p.lat,x.p.lon],{icon:L.divIcon({className:'map-pin',html:String(i+1),iconSize:[30,30],iconAnchor:[15,15]})}).addTo(mapLayer);marker.on('click',()=>selectMapPlace(x.key,false));mapMarkers.set(x.key,marker);});fitMap();$('#selectedMapPlace').innerHTML='';}
function fitMap(){if(map&&mapBounds.length)map.fitBounds(mapBounds,{padding:[35,35],maxZoom:12,animate:!reduced()});}
function selectMapPlace(key,pan=true){const item=mapItems().find(x=>x.key===key);if(!item)return;document.querySelectorAll('[data-map-row]').forEach(el=>el.classList.toggle('selected',el.dataset.mapRow===key));mapMarkers.forEach((marker,k)=>marker.getElement()?.classList.toggle('selected',k===key));if(pan&&map)map.flyTo([item.p.lat,item.p.lon],Math.max(map.getZoom(),11),{animate:!reduced(),duration:.25});$('#selectedMapPlace').innerHTML=`<p class="editor-label">${placeKind(key)}</p><h2>${esc(item.p.name)}</h2><p>${esc(item.p.address||item.p.en)}</p><div class="inline-actions"><button class="primary-link" data-navigation="${key}">打开地图导航 ↗</button><button data-place="${key}">查看详情</button><button data-day="${item.day}">当天安排</button></div>`;animateContent($('#selectedMapPlace'));}
function navigationBody(key){const p=key.startsWith('hotel:')?DATA.hotels[key.slice(6)]:DATA.places[key];if(!p)return '<p>原路书未提供此地点。</p>';const query=p.address?(p.name+' '+p.address):p.mapQuery||p.en||p.name;const dest=Number.isFinite(p.lat)&&Number.isFinite(p.lon)?p.lat+','+p.lon:query;return `<p>${esc(p.name)}<br>${esc(p.address||p.en||'')}</p><p class="info-caption">外部地图需要联网；目的地来自原路书，出发前核对集合点与道路开放情况。</p><div class="navigation-options">${ext(key.startsWith('hotel:')?hotelLink(key.slice(6)):navLink(p),'Google Maps','primary-link')}${ext('https://maps.apple.com/?q='+encodeURIComponent(query)+'&daddr='+encodeURIComponent(dest),'Apple Maps','primary-link')}<button data-copy="${esc(query)}">复制名称与地址</button></div>`;}
